import { describe, expect, test } from 'bun:test';
import { OperatorRuntime } from '@agentic-ddd/runtime';
import { covers, FakeLlm } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { CreateTask } from '../application/create-task';
import { TaskCompleted, TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

describe('task-operator', () => {
  test(covers(['operator:task-operator', 'criterion:0001/tools'], 'cria e conclui tarefa usando só suas duas tools e publica os eventos'), async () => {
    const repo = new InMemoryTaskRepository();
    const llm = new FakeLlm([
      { content: [{ type: 'tool_call', id: 'c1', name: 'create_task', input: { task_id: 't1', title: 'Comprar pão' } }], stopReason: 'tool_calls' },
      { content: [{ type: 'tool_call', id: 'c2', name: 'complete_task', input: { task_id: 't1' } }], stopReason: 'tool_calls' },
      { content: [{ type: 'text', text: 'Tarefa t1 criada e concluída.' }], stopReason: 'end' },
    ]);
    const runtime = new OperatorRuntime({ llm, modules: [{ name: 'tasks', path: 'app' }], root: process.cwd() });
    await runtime.register(TaskOperator, new Map<any, any>([[CreateTask, new CreateTask(repo)], [CompleteTask, new CompleteTask(repo)]]));

    const result = await runtime.run('task-operator', { message: 'Crie a tarefa t1 "Comprar pão" e conclua-a.' });

    expect(result.status).toBe('completed');
    expect(result.output).toBe('Tarefa t1 criada e concluída.');
    expect(llm.requests[0]!.tools.map((t) => t.name)).toEqual(['complete_task', 'create_task']);
    const calls = result.steps.flatMap((s) => s.tools.map((t) => t.call.name));
    expect(calls).toEqual(['create_task', 'complete_task']);
    expect(result.steps.flatMap((s) => s.tools).every((t) => t.result && !t.result.isError)).toBe(true);
    expect((await repo.findById('t1'))?.status).toBe('completed');
    expect(result.events).toHaveLength(2);
    expect(result.events[0]).toBeInstanceOf(TaskCreated);
    expect(result.events[1]).toBeInstanceOf(TaskCompleted);
    expect((result.events[1] as TaskCompleted).payload).toEqual({ taskId: 't1' });
  });
});
